local _, ns = ...

--[[
	Content localization for the journal, in Brazilian Portuguese: the same tables as Locales/ruRU_content.lua,
	keyed by the data's English words (Core/Registry.lua's ns.ApplyLocale lays them over the data).
	Drafted by Claude, for review by a native speaker: names new in WoW: Forever had no official
	name to follow. Every other client skips it.
]]

-- The journal's words where it speaks this language; the tables matched against the client's own
-- text where the client does, previewed or not (ns.LocaleTargets, Locales/enUS.lua).
local L, client = ns.LocaleTargets("ptBR")
if not L then return end

