	["Jarkal Mossmeld, Kargath, Badlands"] = "Jarkal Limuno, Karrath, Ermos",
	["Je'neu Sancrea"] = "Je'neu Sancrea",
	["Je'neu Sancrea, Zoram'gar Outpost, Ashenvale"] = "Je'neu Sancrea, Assentamento Zoram'gar, Vale Gris",
