	["Jordan Stilwell — Gates of Ironforge"] = "Jardel Calmafonte — Portões de Altaforja",
	["Jordan Stilwell, Gates of Ironforge, Dun Morogh"] = "Jardel Calmafonte, Portões de Altaforja, Dun Morogh",
	["Journey to the Marsh"] = "Jornada ao pântano",
	["Judgment and Redemption"] = "Julgamento e redenção",
	["Keep the ring, or find whoever made the mark engraved inside its band."] = "Fique com o anel ou encontre quem fez a marca gravada na parte de dentro do aro.",
	["Keeper Bel'dugur"] = "Guardião Bel'dugur",
