	["Shen'dralar Ancient, inside the dungeon"] = "Anciã Shen'dralar, dentro da masmorra",
	["Shield Slam stuns the tank; at 15% health he runs for help."] = "A Escudada atordoa o tanque; com 15% de vida, ele foge em busca de ajuda.",
	["Shields her against damage for up to 30 seconds. A priest or a shaman can remove it."] = "Protege-a contra dano por até 30 segundos. Um sacerdote ou um xamã pode remover o escudo.",
	["Shields himself against spells for a while."] = "Ele se protege contra feitiços por um tempo.",
	["Shoni the Shilent — Dwarven District, Stormwind"] = "Shoni, a Shilenchiosa — Distrito dos Anões, Ventobravo",
