	["The Path of the Righteous"] = "O caminho do íntegros",
	["The Platinum Discs"] = "Os discos de platina",
	["The Pool of Ask'ar"] = "O Poço de Ask'Ar",
	["The Power to Destroy..."] = "O poder de destruir...",
